  'room.jardin.desc': '心の休息：ガイド付き瞑想、呼吸法、感謝日記。',
  'room.garage.desc': '愛車のメンテナンスと整備記録。',
  'room.diario.desc': 'カテゴリー別の毎日のニュース。',
  'room.hobbies.desc': '趣味と創作プロジェクト。',
  'room.idiomas.desc': '語学学習：AI先生、間隔反復の単語学習、レベル別シラバス、練習問題。',
  'room.calendario.desc': 'カレンダー：日・週・月ごとの予定とルーティン。',
  'room.caminos.desc': 'マップにレーストラック、線路、ジェットコースターを配置。',
  'room.canchas.desc': 'マップにサッカー・テニス・バスケ・野球のコートを設置。',
  'room.huerto.desc': '畑を整えて種をまき、水やりしてリアルタイムで収穫。',
  'room.granja.desc': 'ニワトリ・ブタ・ヤギ・ヒツジ・ウシ・ウマを育て、同じエディターで飼料も栽培。',
  'room.ideas.desc':
    'アイデア日記とブレインストーミング、自由なキャンバス上の10種類のマインドマップ形式（マインドマップ、ツリー、タイムライン、サイクル、ピラミッド、ベン図など）、決断のための8種類の図（メリット・デメリット、フォースフィールド分析、SWOT分析、アイゼンハワーマトリクス、意思決定木、ティアリスト、重み付け意思決定マトリクス、特性要因図）を、手書きでもAIでも。',
  'room.metas.desc':
    '家じゅうの「やると決めたこと」：サブ目標とステップまで含めた目標の一覧、AIがそれぞれに提案するプラン（日付つきのフェーズが本物のサブ目標に変わります）、そして、すべてが時間軸の上でそれぞれの期間を占めるスケジュール。',
  'room.computo.desc':
    '計算室：数式帳（数学・物理・化学を収録、編集可能）がついた関数電卓と、8つのモード――4種類（2D・極座標・パラメトリック・3D曲面）のグラフ、2進数・16進数、行列、連立方程式、単位変換、チップ計算、比例式――そしてExcelやPDFに出力できる表計算。',
