  'ideas.tipoDesc.matriz': 'いくつかの選択肢を、本当に重視する基準で採点します。',
  'ideas.guia.matriz': '各基準は自分にとっての重要度で重み付けされ（1〜5）、選択肢はそれぞれ1〜5点で採点されます。合計は点数×重みで計算されるので、どうでもいい基準で高得点でも勝てません。',
  'ideas.matriz.criterio': '基準',
