  'ideas.matriz.criterioN': '基準{n}',
  'ideas.matriz.opcionN': '選択肢{n}',
  'ideas.matriz.ayuda': '名前をタップすると変更、重みをタップするとその基準の重要度を上げられます。各マスをタップして1〜5点を付けてください。合計は重みを掛けた値です。',
  'ideas.ejemplo.ver': '例を見る',
  'ideas.ejemplo.chip': '例',
  'ideas.ejemplo.comoFunciona': 'この形式はどう使うの？',
  'ideas.guia.mental': 'マインドマップはテーマを四方八方に広げます。中心にアイデア、その周りに大きな枝、さらに枝から細部がぶら下がる形です。順序を決める前に、頭の中を空っぽにするためのものです。',
  'ideas.guia.arbol': 'ツリーは組織図のように、全体から詳細へと分かれていきます。バラバラなアイデアではなく、カテゴリーがサブカテゴリーに分かれる場合に使います。',
  'ideas.guia.etimologia': '語源ツリーは単語を分解します。由来、意味、使い方、そして同じ語族の単語まで分かります。ブレインストーミングの前に概念を掘り下げたり、名前を考えたりするときに便利です。',
  'ideas.tipo.etimologia': '語源ツリー',
  'ideas.tipoDesc.etimologia': '単語を分解：由来・意味・使い方・語族。',
  'ideas.guia.llaves': '括弧図は全体を左から右へパーツに分けます——昔ながらのアウトライン形式です。物事を分解して構成要素を見るのに向いています。',
  'ideas.guia.circulo': '円形図はテーマを中心に置き、知っていることすべてを階層なしで周りに配置します。概念を探ったり、試験前に復習したりするのに便利です。',
  'ideas.guia.flujo': 'フローチャートは矢印で手順をつなぎます。ステップをタップし、図形ボタンで開始・分岐・終了に変更できます。ひし形はYes/Noの質問です。',
  'ideas.guia.linea': '年表は日付順に並びます。節目は線の上下に交互に配置され、詳細は外側にぶら下がります。節目の最初に年を入れると、それだけで読みやすくなります。',
  'ideas.guia.ciclo': 'サイクル図は繰り返す段階をつなぎます。各段階は起点から追加してください——前の段階にぶら下げないよう背景をタップします——そうすると自動的に円周上に広がります。',
  'ideas.guia.piramide': 'ピラミッド図は階層を積み重ねます。それぞれが下の階層の上に乗るので、土台こそ最初に固めるべきものです。階層名を2回タップすると変更できます。',
  'ideas.guia.venn': 'ベン図は2つの集合を向き合わせ、共通点は重なる部分に入ります。追加する前に下部バーで領域を選ぶか、項目を別の項目にドラッグすると自動的に移動します。',
  'ideas.guia.comparacion': '比較図は2つのテーマを列に並べ、共通点を中央に置きます。表形式のベン図のようなもので、項目が多いときに読みやすくなります。',
  'ideas.guia.proscontras': '各項目は1〜5の重みを持ちます。選択して下部バーの−＋で調整してください。各列は下に合計が出るので、「どちらのリストが長いか」で決めなくて済みます。',
  'ideas.guia.fuerzas': 'フォースフィールド図は変化を見つめます。左に後押しする力、右に妨げる力、それぞれに重みがあります。右側が勝っているなら、まず最も重い力から取り組みましょう。',
  'ideas.guia.foda': '強みと弱みは自分自身のもの、機会と脅威は外からやってきます。迷ったら、それが自分次第かどうかを考えてみてください。',
  'ideas.guia.eisenhower': '上が重要度、左が緊急度です。「予定に入れる」の象限こそ物事を動かします。ここが空のままだと、一日中火消しに追われることになります。',
  'ideas.guia.decision': '各枝が選択肢とその結果を表します。当たり前に思えても書き出してください。書かれていないものは、比較の対象にすらなりません。',
  'ideas.guia.tier': 'Sが最高、Dが最低です。まだ順位を決められないものは「未分類」で待機します。決まったら該当の行にドラッグしてください。',
  'ideas.guia.ishikawa': '頭が問題で、それぞれの骨が原因のグループ（方法・設備・材料・測定…）です。探すのは原因であって、解決策は後回しにしてください。',
