  'chat.manual.nota.cocina': 'AIを使うと料理の写真も認識し、栄養素を推定して記録します。チャットで頼んだレシピや食事プランには画像が付き、表示に少し時間がかかり、表示されたクレジットを消費します。',
  'chat.manual.nota.cuartos': '部屋の作成・名前変更・整理ができます。「削除」で家から部屋がなくなります。',
  'chat.manual.nota.despacho': 'AIを使うとレシート写真も添付でき、支出として記録されます。',
  'chat.manual.nota.diario': 'その日の文化コーナーとアシスタントによる配達は、アプリ内でAIを使っています。',
  'chat.manual.nota.ejercicio': 'AIを使うと、スケジュールでトレーニングプラン（✨ボタン）を作成でき、アプリ内でエクササイズの説明画像も見られます。',
  'chat.manual.nota.entretenimiento': 'テーブルゲーム：スネーク、テトリス、チェス、チェッカー、数独、神経衰弱、ポン、ホッケー、サイモン、コネクトフォー、スペース、恐竜など',
  'chat.manual.nota.garage': '乗り物（自転車、バイク、車、UFO）は「キャラクターと乗り物」にあります。',
  'chat.manual.nota.granja': '動物：ニワトリ、ブタ、ヤギ、ヒツジ、ウシ、ウマ。エサは「食」で収穫したものです。',
  'chat.manual.nota.hobbies': 'スケジュールでAIプラン（✨）を頼むと、プロジェクトを前に進められます。',
  'chat.manual.nota.huerto': '作物：ニンジン、レタス、ヒマワリ、トマト、トウモロコシ、カボチャ',
  'chat.manual.nota.idiomas': '中にはレベル別の会話先生、チャットからのカード、テーマ別カード（AI）があります。',
  'chat.manual.nota.configuraciones':
    'エディタの設定タブにあるすべて：言語、外観（ライト、ダーク、透明）、アイコンスタイル、インターフェースのテーマとフォント、パネルのガラス、マップの見た目のスタイル（通常、コミック、ミニチュア、レトロ、ネオン）とそのエフェクト、通知、バックアップ。',
  'chat.manual.aviso.configuraciones': 'ログイン、バックアップの復元、データの削除はチャットからは行えません。アシスタントがその画面を開くので、自分で確認してください。',
  'chat.manual.nota.interfaz':
    '家のテーマ、空の背景、環境音楽、Wrappedの振り返り。音楽のムード：calma, festivo, nocturno, chiptune, acogedor, energia, estudio, arcade, bosque, viaje, carrera, cajita',
  'chat.manual.nota.mapa': '方角：北、南、東、西（上、下、左、右も可）',
  'chat.manual.nota.memoria': 'アシスタントはセッションをまたいで内容を覚えています。クリップで写真を添付するか、マイクで話して入力できます。@appで記録先を指定できます。',
  'chat.manual.nota.objetos':
    'AIなしのカタログ：ランプ、椅子、テーブル、植物、ギター、ラグ、収納箱、絵、ボール、本。それ以外はAIが3Dモデルとして生成し、持ち物に保存します。2D画像は「〜の画像を作って」と頼むと、チャットに残ります。',
  'chat.manual.nota.personaje': '服：帽子、メガネなど。パーツ：頭、胴体、脚。乗り物：自転車、バイク、車、UFO（Space/Shiftで飛行）。視点：アイソメトリック、三人称、一人称（Vキー）。',
  'chat.manual.nota.sala': 'AIを使うと、新しい場所が自動でジオコーディングされ、世界地図にピンで表示されます。',
  'chat.manual.nota.superficies': '色：赤、青、緑など、または#の16進コード。床の素材と屋根の形はエディタのカタログから選べます。',
  'chat.manual.nota.teclado': 'キーボードで遊ぶためのショートカットです。チャットには入力しません。家の中で使います。入力欄に文字を入れているときや部屋を開いているときは効きません。',
  'chat.manual.notaSeccion.apps':
    '各アプリは、話したとおりの言葉でそれぞれのデータを記録し（@appで記録先を指定可能）、名前を言えばメニューが開きます。「AIを使う」の例は必ずAI利用1回分を消費します（Proプランまたは自分のキー）。カスタムテンプレートもチャットから記録・名前で起動できます。注：オフライン解析はスペイン語専用のため、日本語ではほとんどのコマンドがAI経由になります。',
  'chat.manual.notaSeccion.mapa': '菜園、牧場、コース、コートは部屋の外、3Dマップ上にあります。',
