  'tut.terminar': '完了',
  'tut.voz': 'ステップを音声で読み上げる',
  'tut.appSinCuarto': 'このアプリはまだどの部屋にもありませんので、ここで説明します。使うには「メニュー›テンプレート」で割り当ててください。',
  'tut.errorCarga': 'そのチュートリアルを読み込めませんでした。接続を確認して、もう一度お試しください。',
  'tut.preparandoDemo': 'デモハウスでそのアプリの一年分を準備しています。ツアーはまもなく始まります…',
  'tut.selector.titulo': 'どのチュートリアルを見ますか？',
  'tut.selector.hint': '黄色く光っているエリアをタップするか、まず全体の説明から始めてください。',
  'tut.selector.general': '全体チュートリアル',
  'tut.selector.cancelar': 'キャンセル',
  'tut.selector.apps': 'またはアプリのチュートリアル：',
  'tut.selector.infra': 'またはマップに施設を作る：',
