  'jardin.hist': 'セッション',
  'jardin.hist.vacio': 'ここに心を落ち着けたセッションが記録されます。',
  'jardin.hist.min': '{n}分',
  'hobbies.sesion.todas': 'セッション',
  'despacho.m.sinRegistros': '取引の記録がありません。',
  'room.agenda.desc': 'スケジュールです。仕事のタスク、イベントとプロジェクト、通院の予定と薬、ペットとその世話、誕生日つきの連絡先帳をまとめます。',
  'agenda.tab.trabajo': '仕事',
  'agenda.tab.salud': '健康',
  'agenda.tab.personas': '連絡先',
